import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { SortAsc, LayoutGrid, List } from 'lucide-react';
import SearchBar from '../components/SearchBar';
import PropertyCard from '../components/PropertyCard';
import { MOCK_PROPERTIES } from '../data/mockData';
import { useAuth } from '../context/AuthContext';
import './Listings.css';

export default function Listings() {
  const location = useLocation();
  const { user } = useAuth();
  const [properties, setProperties] = useState(MOCK_PROPERTIES);
  const [sort, setSort] = useState('newest');
  const [view, setView] = useState('grid');
  const [wishlist, setWishlist] = useState(() => {
    const saved = localStorage.getItem('propconnect_wishlist');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    const params = new URLSearchParams(location.search);
    applyFilters({
      keyword: params.get('keyword') || '',
      type: params.get('type') || '',
      listingType: params.get('listingType') || '',
      city: params.get('city') || '',
      minPrice: params.get('minPrice') || '',
      maxPrice: params.get('maxPrice') || '',
      bedrooms: params.get('bedrooms') || '',
    });
  }, [location.search]);

  const applyFilters = (f) => {
    let result = [...MOCK_PROPERTIES];
    if (f.keyword) result = result.filter(p =>
      [p.title, p.suburb, p.city, p.address].some(s => s?.toLowerCase().includes(f.keyword.toLowerCase()))
    );
    if (f.type) result = result.filter(p => p.type === f.type);
    if (f.listingType) result = result.filter(p => p.listingType === f.listingType);
    if (f.city) result = result.filter(p => p.city.toLowerCase().includes(f.city.toLowerCase()));
    if (f.minPrice) result = result.filter(p => p.price >= Number(f.minPrice));
    if (f.maxPrice) result = result.filter(p => p.price <= Number(f.maxPrice));
    if (f.bedrooms) result = result.filter(p => p.bedrooms >= Number(f.bedrooms));
    setProperties(result);
  };

  const sorted = [...properties].sort((a, b) => {
    if (sort === 'newest') return new Date(b.createdAt) - new Date(a.createdAt);
    if (sort === 'price_asc') return a.price - b.price;
    if (sort === 'price_desc') return b.price - a.price;
    return 0;
  });

  const toggleWishlist = (id) => {
    const updated = wishlist.includes(id) ? wishlist.filter(i => i !== id) : [...wishlist, id];
    setWishlist(updated);
    localStorage.setItem('propconnect_wishlist', JSON.stringify(updated));
  };

  return (
    <div>
      <div className="page-header">
        <div className="container">
          <h1>Browse Properties</h1>
          <p>Find your perfect home, investment, or commercial space</p>
        </div>
      </div>

      <div className="container section">
        <div className="listings-search-wrap">
          <SearchBar onSearch={applyFilters} compact />
        </div>

        <div className="listings-toolbar">
          <p className="results-count"><strong>{sorted.length}</strong> {sorted.length === 1 ? 'property' : 'properties'} found</p>
          <div className="toolbar-right">
            <select value={sort} onChange={e => setSort(e.target.value)} className="sort-select">
              <option value="newest">Newest First</option>
              <option value="price_asc">Price: Low to High</option>
              <option value="price_desc">Price: High to Low</option>
            </select>
            <div className="view-toggle">
              <button className={view === 'grid' ? 'active' : ''} onClick={() => setView('grid')}><LayoutGrid size={18} /></button>
              <button className={view === 'list' ? 'active' : ''} onClick={() => setView('list')}><List size={18} /></button>
            </div>
          </div>
        </div>

        {sorted.length === 0 ? (
          <div className="empty-state">
            <SortAsc size={48} />
            <h3>No properties found</h3>
            <p>Try adjusting your search filters</p>
          </div>
        ) : (
          <div className={view === 'grid' ? 'grid-3' : 'list-view'}>
            {sorted.map(p => (
              <PropertyCard
                key={p.id}
                property={p}
                onWishlist={user ? toggleWishlist : null}
                isWishlisted={wishlist.includes(p.id)}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
